// Neakasa M1 unified cards. Images are embedded in this single resource.
const NEAKASA_ASSETS = {"waste":"data:image/webp;base64,","visits":"data:image/webp;base64,","sand":"data:image/webp;base64,","neakasa":"data:image/webp;base64,","level":"data:image/webp;base64,","clean":"data:image/webp;base64,","calibrate":"data:image/webp;base64,"};

const STYLE = `:host{display:block}ha-card{border-radius:20px;padding:12px;overflow:hidden}.title{text-align:center;font-size:19px;font-weight:600}.subtitle{text-align:center;font-size:14px;color:var(--secondary-text-color)}.device{display:block;width:190px;height:190px;max-width:100%;object-fit:contain;margin:10px auto 12px}.columns{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:4px}.tile{min-width:0;border:0;background:transparent;color:var(--primary-text-color);text-align:center;padding:8px 2px;cursor:pointer;font:inherit}.tile[disabled]{opacity:.4;cursor:default}.tile img{height:36px;width:36px;object-fit:contain}.tile .value{font-size:17px;font-weight:700}.tile .label{font-size:12px;color:var(--secondary-text-color);margin-top:4px}.action img{height:42px;width:42px;object-fit:contain}.action .label{font-size:14px;color:var(--primary-text-color)}.day{font-size:13px;font-weight:600;color:var(--secondary-text-color);padding:6px 0 12px}.entry{display:grid;grid-template-columns:44px 1fr;gap:10px;padding-bottom:14px;position:relative}.entry:not(:last-child):before{content:'';position:absolute;left:19px;top:42px;bottom:0;border-left:1px dotted var(--divider-color)}.avatar{width:39px;height:39px;border-radius:50%;background:var(--secondary-background-color);display:flex;align-items:center;justify-content:center;overflow:hidden}.avatar img{width:100%;height:100%;object-fit:cover}.time{font-weight:600;font-size:15px}.text{font-size:13px;color:var(--secondary-text-color);margin-top:4px;line-height:1.4;overflow-wrap:anywhere}.text strong{color:var(--primary-text-color)}.overlay{position:fixed;inset:0;z-index:10000;background:#0008;display:flex;align-items:center;justify-content:center}.dialog{min-width:260px;padding:20px;background:var(--card-background-color);color:var(--primary-text-color);border-radius:14px}.dialog select{width:100%;padding:8px;margin-top:12px}.actions{display:flex;justify-content:flex-end;gap:12px;margin-top:18px}.actions button{cursor:pointer;padding:8px 12px}`;
const make=(tag,cls,txt)=>{const e=document.createElement(tag);if(cls)e.className=cls;if(txt!==undefined)e.textContent=txt;return e;};
const valid=v=>v!=null&&!['unknown','unavailable',''].includes(String(v).toLowerCase());
function shell(host){if(!host.shadowRoot)host.attachShadow({mode:'open'});host.shadowRoot.replaceChildren();const css=make('style');css.textContent=STYLE;host.shadowRoot.append(css);const card=make('ha-card');host.shadowRoot.append(card);return card;}
function photo(parent,source,fallback){if(!source){parent.append(make('span',null,fallback));return;}const img=make('img');img.src=source;img.alt='';img.onerror=()=>img.replaceWith(make('span',null,fallback));parent.append(img);}
class NeakasaM1Card extends HTMLElement{
 setConfig(config){if(!config?.entities?.status)throw Error('entities.status required');this.config={name:"Cat's Toilet",confirm_actions:true,...config};this.draw();}
 set hass(h){this._hass=h;this.draw();}
 connectedCallback(){if(!this._timer)this._timer=setInterval(()=>this.draw(),60000);}
 disconnectedCallback(){clearInterval(this._timer);this._timer=null;}
 state(id){return id&&this._hass?.states[id];}
 more(id){if(id)this.dispatchEvent(new CustomEvent('hass-more-info',{bubbles:true,composed:true,detail:{entityId:id}}));}
 dialog(title,choices,callback){const overlay=make('div','overlay');const box=make('div','dialog');box.setAttribute('role','dialog');box.append(make('div','title',title));let select;if(choices){select=make('select');for(const v of choices){const o=make('option',null,`${v}%`);o.value=String(v);select.append(o);}const current=this.state(this.config.entities.calibrate)?.state;const preferred=this.config.calibration?.default??current??90;select.value=String(preferred);box.append(select);}const buttons=make('div','actions');for(const [label,act] of [['Cancel',()=>overlay.remove()],[choices?'Calibrate':'Confirm',()=>{overlay.remove();Promise.resolve(callback(select?Number(select.value):undefined)).catch(error=>console.error('[neakasa-m1-card]',error));}]]){const button=make('button',null,label);button.onclick=act;buttons.append(button);}box.append(buttons);overlay.append(box);overlay.onclick=event=>{if(event.target===overlay)overlay.remove();};this.shadowRoot.append(overlay);}
 action(key){const id=this.config.entities[key];if(!id||!this._hass)return;const service=(value)=>key==='calibrate'?this._hass.callService('number','set_value',{entity_id:id,value}):this._hass.callService('button','press',{entity_id:id});if(key==='calibrate')this.dialog('Cat Litter Calibration',this.config.calibration?.options??[50,60,70,80,90,100],service);else if(this.config.confirm_actions===false)service().catch(console.error);else this.dialog(`Start ${key}?`,null,service);}
 draw(){if(!this.config||!this._hass)return;if(this.shadowRoot?.querySelector('.overlay'))return;const card=shell(this);card.append(make('div','title',this.config.name));const e=this.config.entities,s=this.state(e.status);let status=valid(s?.state)?s.state.replaceAll('_',' ').replace(/^./,c=>c.toUpperCase()):'Unavailable';if(s?.last_updated){const seconds=Math.max(0,Math.floor((Date.now()-Date.parse(s.last_updated))/1000));const n=seconds<3600?Math.floor(seconds/60):seconds<86400?Math.floor(seconds/3600):Math.floor(seconds/86400);const unit=seconds<3600?'minute':seconds<86400?'hour':'day';status+=seconds<60?' (just now)':` (${n} ${unit}${n===1?'':'s'} ago)`;}const label=make('div','subtitle',status);label.style.cursor='pointer';label.onclick=()=>this.more(e.status);card.append(label);const main=make('img','device');main.src=NEAKASA_ASSETS.neakasa;main.alt=this.config.name;card.append(main);
 const metrics=make('div','columns');for(const [key,title,fmt] of [['litter','Cat litter',v=>valid(v)?`${v}%`:'—'],['waste','Waste bin',v=>v==='on'?'Full':v==='off'?'Normal':'—'],['visits','Visits today',v=>valid(v)?v:'—']]){const b=make('button','tile');b.type='button';photo(b,NEAKASA_ASSETS[key],'');b.append(make('div','value',fmt(this.state(e[key])?.state)),make('div','label',title));b.onclick=()=>this.more(e[key]);metrics.append(b);}card.append(metrics);
 const controls=make('div','columns');for(const [key,title] of [['clean','Clean'],['level','Level'],['calibrate','Calibrate']]){const b=make('button','tile action');b.type='button';photo(b,NEAKASA_ASSETS[key],'');b.append(make('div','label',title));b.disabled=!e[key]||!valid(this.state(e[key])?.state);b.onclick=()=>this.action(key);controls.append(b);}card.append(controls);}
 getCardSize(){return 5;}
 static getStubConfig(){return {entities:{status:'sensor.neakasa_m1_status'}};}
}
class NeakasaActivityCard extends HTMLElement{
 setConfig(config){if(!config?.entity)throw Error('entity required');this.config={title:'',limit:10,days:7,cats:[],...config};this.records=null;this._last=0;this.draw();}
 set hass(h){this._hass=h;if(!this.records||Date.now()-this._last>=60000)this.load();}
 connectedCallback(){if(!this._timer)this._timer=setInterval(()=>this.load(),60000);}
 disconnectedCallback(){clearInterval(this._timer);this._timer=null;}
 async load(){if(!this._hass||!this.config||this._loading)return;this._loading=true;const end=new Date(),start=new Date(end.getTime()-Math.max(1,Number(this.config.days)||7)*86400000);const q=new URLSearchParams({filter_entity_id:this.config.entity,end_time:end.toISOString(),significant_changes_only:'0',minimal_response:'0',no_attributes:'1'});try{const result=await this._hass.callApi('GET',`history/period/${encodeURIComponent(start.toISOString())}?${q}`);this.records=(result[0]||[]).filter(item=>valid(item.state)).map(item=>({message:item.state,time:item.last_changed||item.last_updated})).filter(item=>item.time).sort((a,b)=>Date.parse(b.time)-Date.parse(a.time)).slice(0,Math.max(1,Number(this.config.limit)||10));this.error=null;this._last=Date.now();}catch(error){this.error=error.message||String(error);}finally{this._loading=false;this.draw();}}
 draw(){if(!this.config)return;const card=shell(this);if(this.config.title)card.append(make('div','title',this.config.title));if(!this.records){card.append(make('div','subtitle',this.error||'Loading activity…'));return;}if(!this.records.length)card.append(make('div','subtitle','No recent activity'));let day='';for(const record of this.records){const time=new Date(record.time),current=time.toLocaleDateString('en-GB',{weekday:'short',day:'numeric',month:'short'});if(current!==day){card.append(make('div','day',current));day=current;}const message=record.message.replace(/\s*\(\d+\)\s*$/,'').trim();const cats=Array.isArray(this.config.cats)?this.config.cats:[];const cat=cats.find(c=>typeof c?.name==='string'&&c.name.length&&message.toLowerCase().includes(c.name.toLowerCase()));const entry=make('div','entry'),avatar=make('div','avatar');if(cat?.image)photo(avatar,cat.image,'🐱');else{const icon=make('ha-icon');icon.setAttribute('icon',cat?'mdi:cat':/clean/i.test(message)?'mdi:broom':/level/i.test(message)?'mdi:spirit-level':'mdi:information-outline');avatar.append(icon);}const content=make('div');content.append(make('div','time',time.toLocaleTimeString('en-GB',{hour:'2-digit',minute:'2-digit'})));const description=make('div','text'),i=cat?message.toLowerCase().indexOf(cat.name.toLowerCase()):-1;if(i>=0)description.append(document.createTextNode(message.slice(0,i)),make('strong',null,message.slice(i,i+cat.name.length)),document.createTextNode(message.slice(i+cat.name.length)));else description.textContent=message;content.append(description);entry.append(avatar,content);card.append(entry);}if(this.error)card.append(make('div','subtitle',`Refresh failed: ${this.error}`));}
 getCardSize(){return 5;}
 static getStubConfig(){return {entity:'input_text.neakasa_last_event'};}
}
if(!customElements.get('neakasa-m1-card'))customElements.define('neakasa-m1-card',NeakasaM1Card);
if(!customElements.get('neakasa-activity-card'))customElements.define('neakasa-activity-card',NeakasaActivityCard);
window.customCards=window.customCards||[];
for(const item of [{type:'neakasa-m1-card',name:'Neakasa M1',description:'Neakasa M1 device controls'},{type:'neakasa-activity-card',name:'Neakasa Activity',description:'Cat activity log from Recorder'}])if(!window.customCards.some(card=>card.type===item.type))window.customCards.push(item);